OLD_AGG = ("**合计未完成验收项**：**75**（二级任务 · **逐目录实测**）＋ **16**（一级特有）＋ **0**"
            "（实盘读数指针 · **4 项已闭合**）＋ **55**（横切）＝ **146**")
NEW_AGG = ("**合计未完成验收项**：**36**（二级任务 · **逐目录实测**）＋ **8**（一级特有）＋ **0**"
            "（实盘读数指针 · **4 项已闭合**）＋ **55**（横切）＝ **99**")


def main() -> None:
    text = mdpatch.read(DOC)
    lines = text.split(NL)

    head = [i for i, line in enumerate(lines) if line.startswith(HEADER)]
    if len(head) != 1:
        raise SystemExit("update_p01: table header anchor count %d" % len(head))
    start = head[0]
    tail = [i for i, line in enumerate(lines) if i > start and line.startswith("**合计未完成验收项**")]
    if not tail:
        raise SystemExit("update_p01: aggregate line not found")
    end = tail[0]

    rows = [HEADER, "|---|---|---|---|---|---|---:|---|"] + ROWS_TEXT.split(NL)
    while rows and rows[-1] == "":
        rows.pop()
    lines[start:end] = rows + [""]
    text = NL.join(lines)

    text = mdpatch.replace_once(text, OLD_AGG, NEW_AGG, "aggregate")
    text = mdpatch.insert_after(text, NEW_AGG, NOTE_TEXT, "note")

    mdpatch.write(DOC, text)
    print("update_p01: ok")


if __name__ == "__main__":
    main()

